<?php
namespace App\Services;
use App\Models\{AttendanceEvent,TrainingSession}; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class TrainingAttendanceIntegrationService
{
 public function __construct(private TrainingAudienceResolverService$audience,private AttendanceEventService$attendance,private TrainingSessionService$sessions){}
 public function freeze(TrainingSession$s,int$user):array{if($s->attendance_event_id)return['event'=>$s->attendanceEvent,'token'=>null,'codes'=>[]];return DB::transaction(function()use($s,$user){$employees=$this->audience->resolve($s);$token=Str::random(64);$event=AttendanceEvent::create(['company_id'=>$s->company_id,'uuid'=>(string)Str::uuid(),'attendable_type'=>'training_session','attendable_id'=>$s->id,'title'=>$s->title,'description'=>$s->description,'event_type'=>'training_session','starts_at'=>$s->scheduled_start_at,'ends_at'=>$s->scheduled_end_at,'attendance_opens_at'=>$s->scheduled_start_at->copy()->subMinutes(config('training.attendance_open_minutes',30)),'attendance_closes_at'=>$s->scheduled_end_at->copy()->addMinutes(config('training.attendance_close_minutes',30)),'status'=>'open','requires_signature'=>$s->requires_signature,'allows_external_attendees'=>true,'public_access_enabled'=>true,'access_token_hash'=>hash('sha256',$token),'access_token_expires_at'=>$s->scheduled_end_at->copy()->addMinutes(30),'created_by'=>$user,'updated_by'=>$user]);$codes=[];foreach($employees as$employee){$code=strtoupper(Str::random(10));$p=$event->participants()->create(['uuid'=>(string)Str::uuid(),'participant_type'=>'employee','employee_id'=>$employee->id,'name_snapshot'=>$employee->nombre_completo,'role_snapshot'=>$employee->cargo,'department_snapshot'=>$employee->area_departamento,'email'=>$employee->email_personal,'expected'=>true,'invitation_status'=>'pending','credential_hash'=>hash('sha256',$code),'credential_expires_at'=>$event->attendance_closes_at]);$codes[]=['name'=>$p->name_snapshot,'code'=>$code];}$snapshot=['title'=>$s->title,'topic'=>$s->topic?->name,'objectives'=>$s->topic?->general_objective,'audience'=>$s->audience_description,'instructor'=>$s->instructorEmployee?->nombre_completo??$s->externalInstructor?->name,'scheduled_start_at'=>$s->scheduled_start_at->toIso8601String(),'modality'=>$s->modality,'participants'=>$employees->count()];$s->update(['attendance_event_id'=>$event->id,'called_snapshot'=>$snapshot,'status'=>'called','updated_by'=>$user]);$this->attendance->audit($event,'attendance_event_created',$user,['source'=>'training_session','participants'=>$employees->count()]);$this->sessions->audit($s,'training_audience_frozen',$user,['participants'=>$employees->count()]);$this->sessions->audit($s,'training_attendance_enabled',$user);return compact('event','token','codes');});}
}
